def fill_only_horizontal(grid):
    """Fill 1s with 2s ONLY horizontally between pattern cells"""
    rows, cols = len(grid), len(grid[0])
    pattern_val = 4
    result = [row[:] for row in grid]

    for r in range(rows):
        pattern_cols = [c for c in range(cols) if grid[r][c] == pattern_val]
        for i in range(len(pattern_cols) - 1):
            for c in range(pattern_cols[i] + 1, pattern_cols[i+1]):
                if result[r][c] == 1:
                    result[r][c] = 2

    return result

